  "overviewHtml": "<p>\n  <img src=\"https://raw.githubusercontent.com/rdlabo-dev/ionic-theme-ios27/ios27-v2.0.0/screenshots/ios27-settings.png\" width=\"32%\" alt=\"iOS-27-Theme: Einstellungen im hellen Modus mit einer Liquid Glass-Suchleiste\">\n  <img src=\"https://raw.githubusercontent.com/rdlabo-dev/ionic-theme-ios27/ios27-v2.0.0/screenshots/ios27-settings-dark.png\" width=\"32%\" alt=\"iOS-27-Theme: Einstellungen im dunklen Modus\">\n  <img src=\"https://raw.githubusercontent.com/rdlabo-dev/ionic-theme-ios27/ios27-v2.0.0/screenshots/ios27-library.png\" width=\"32%\" alt=\"iOS-27-Theme: Bibliothek mit Liquid Glass-Schaltflächen und Tab-Leiste\">\n</p>",
